SELECT CASE WHEN s.browser IN ('Edge', 'Firefox') THEN 'priority' ELSE 'other' END browser_group, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(we.event_type))) event_type_values FROM web_events we JOIN sessions s ON s.id = we.session_id LEFT JOIN customers c ON s.customer_id = c.id WHERE c.credit_limit >= 11000 GROUP BY CASE WHEN s.browser IN ('Edge', 'Firefox') THEN 'priority' ELSE 'other' END
